      { t = "Lleva el collar a Billy Maclure ([El collar perdido]) y acepta [Un pastel para Billy]. Mata jabalíes colmillopétreo alrededor de los viñedos para [Un pastel para Billy]: ellos y los osos jóvenes sueltan los viales de [Una oferta tentadora], y las flores que pide crecen al sur de la granja.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Entregar: El collar perdido (Billy Maclure)", q = 85, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Recoger: Un pastel para Billy (Billy Maclure)", q = 86, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 41.5, y = 87.3, n = "Objetivo: Un pastel para Billy", q = 86, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 38.7, y = 87.6, n = "Objetivo: Una oferta tentadora", q = 99130, a = "C" } } },
      { t = "Entrega [Un pastel para Billy] a \"Tía\" Bernice Pedregosa, en la granja, y acepta [Vuelve con Billy]. Lleva el pastel a Billy Maclure y acepta [Dientes de oro].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Entregar: Un pastel para Billy (\"Tía\" Bernice Pedregosa)", q = 86, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Recoger: Vuelve con Billy (\"Tía\" Bernice Pedregosa)", q = 84, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Entregar: Vuelve con Billy (Billy Maclure)", q = 84, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Recoger: Dientes de oro (Billy Maclure)", q = 87, a = "A" } } },
      { t = "Mina Abisal, al norte de la granja: explórala ([La Mina Abisal]) y mata kóbolds para [Las velas de los kóbolds], [Intercambio de polvo de oro] y [Devolución de libros] (Nimsy, dentro, lleva el libro de los elementales). Dentdoro anda por la parte de arriba ([Dientes de oro]).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 39.7, y = 80.9, n = "Mina Abisal", q = 62, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.8, n = "Objetivo: Las velas de los kóbolds", q = 60, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.7, n = "Objetivo: Intercambio de polvo de oro", q = 47, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.7, n = "Objetivo: Devolución de libros", q = 91775, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 41.7, y = 78.0, n = "Objetivo: Dientes de oro", q = 87, a = "C" } } },
      { t = "Entrega [Dientes de oro] a \"Tía\" Bernice Pedregosa en la granja de los Pedregosa.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Entregar: Dientes de oro (\"Tía\" Bernice Pedregosa)", q = 87, a = "T" } } },
      { t = "Vuelve a Villadorada: entrega [La Mina Abisal] y [Devolución de libros] a Alguacil Dughan (acepta [La Cantera de Jaspe]); [Las velas de los kóbolds] y [Una nota para William] a William Mortero (acepta [Un envío para Ventormenta] y [La recolección de Kelp]); [Intercambio de polvo de oro] y [Una oferta tentadora] a Remy \"Dos Veces\" (acepta [Cebo para el éxito] y [Un peligro con olor a pescado]). Lleva [Un peligro con olor a pescado] a Alguacil Dughan y acepta [Más preocupaciones], y [Cebo para el éxito] a Jason Mathers, en el lago.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: La Mina Abisal (Alguacil Dughan)", q = 62, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: Devolución de libros (Alguacil Dughan)", q = 91775, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Recoger: La Cantera de Jaspe (Alguacil Dughan)", q = 76, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Entregar: Las velas de los kóbolds (William Mortero)", q = 60, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Entregar: Una nota para William (William Mortero)", q = 107, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Recoger: Un envío para Ventormenta (William Mortero)", q = 61, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Recoger: La recolección de Kelp (William Mortero)", q = 112, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Entregar: Intercambio de polvo de oro (Remy \"Dos Veces\")", q = 47, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Entregar: Una oferta tentadora (Remy \"Dos Veces\")", q = 99130, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Recoger: Cebo para el éxito (Remy \"Dos Veces\")", q = 99131, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Recoger: Un peligro con olor a pescado (Rem