    pasos = {
      { t = "Ve al este por el camino hasta la Torre de Azora: Hamish Bergwort te da [Instrumentos delicados] y Blixie Fitzwink, a su lado, [Suministros de encantamiento robados].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 65.1, y = 69.8, n = "Recoger: Instrumentos delicados (Hamish Bergwort)", q = 91723, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 63.2, y = 72.6, n = "Recoger: Suministros de encantamiento robados (Blixie Fitzwink)", q = 91725, a = "A" } } },
      { t = "Cantera de Jaspe, al norte de la torre: explórala hasta el fondo ([La Cantera de Jaspe]) y mata 8 geománticos kóbold ([Instrumentos delicados]).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 63.1, y = 56.1, n = "Objetivo: Instrumentos delicados", q = 91723, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 61.2, y = 50.5, n = "Cantera de Jaspe", q = 76, a = "C" } } },
      { t = "Vuelve a la Torre de Azora: entrega [Instrumentos delicados] y acepta [Instrumentos delicados].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 65.1, y = 69.8, n = "Entregar: Instrumentos delicados (Hamish Bergwort)", q = 91723, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 65.1, y = 69.8, n = "Recoger: Instrumentos delicados (Hamish Bergwort)", q = 91724, a = "A" } } },
      { t = "En el puente del este, Guardia Thomas recibe [Más preocupaciones] y te da [Encuentra a los guardias perdidos] y [Proteger la frontera]: mata merodeadores y osos jóvenes por todo el este para [Proteger la frontera].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Entregar: Más preocupaciones (Guardia Thomas)", q = 35, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Recoger: Encuentra a los guardias perdidos (Guardia Thomas)", q = 37, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Recoger: Proteger la frontera (Guardia Thomas)", q = 52, a = "A" } } },
      { t = "Campamento maderero del este: Sara Timberlain te da [Artículos rojos de lino], Supervisor Raelen, [El cumplimiento del plazo] y Ormin Pelford, [Río abajo].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 79.5, y = 68.8, n = "Recoger: Artículos rojos de lino (Sara Timberlain)", q = 83, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 81.4, y = 66.1, n = "Recoger: El cumplimiento del plazo (Supervisor Raelen)", q = 5545, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 76.5, y = 71.9, n = "Recoger: Río abajo (Ormin Pelford)", q = 91733, a = "A" } } },
      { t = "Al lado de Sara Timberlain, Eldrin enseña Sastrería: apréndela y haz <Madeja de paño de lino> con el paño de lino que guardas.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 79.2, y = 69.0, n = "Eldrin", npc = 1103 } }, comprobar = { oficios = { 197 } } },
      { t = "Al norte del campamento recoge los haces de [El cumplimiento del plazo]. Al oeste está el guardia muerto de [Encuentra a los guardias perdidos]: entrégala y acepta [Descubre el destino de Rolf]. El cadáver de Rolf está al nordeste ([Descubre el destino de Rolf]): acepta [Informa a Thomas].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 80.3, y = 61.1, n = "Objetivo: El cumplimiento del plazo", q = 5545, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 72.7, y = 60.3, n = "Entregar: Encuentra a los guardias perdidos (Un cadáver medio comido)", q = 37, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 72.7, y = 60.3, n = "Recoger: Descubre el destino de Rolf (Un cadáver medio comido)", q = 45, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 79.8, y = 55.5, n = "Entregar: Descubre el destino de Rolf (Cadáver de Rolf)", q = 45, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 79.8, y = 55.5, n = "Recoger: Informa a Thomas (Cadáver de Rolf)", q = 71, a = "A" } } },
      { t = "Lago del nordeste: mata zahoríes bribones Defias en la orilla ([Instrumentos delicados]); también sueltan los pañuelos de [Artículos rojos de lino]. Los gnolls del noroeste del lago tienen los suministros de [Suministros de encantamiento robados]. Si ves a Elmpaw, mátalo: su cabeza empieza [La cabeza de Elmpaw].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74.1, y = 51.5, n = "Objetivo: Instrumentos delicados", q = 91724, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 67.3, y = 41.3, n = "Objetivo: Suministros de encantamiento robados", q = 91725, a = "C" } } },
      { t = "Vuelve a la Torre de Azora y entrega [Instrumentos delicados] y [Suministros de encantamiento robados].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 65.1, y = 69.8, n = "Entregar: Instrumentos delicados (Hamish Bergwort)", q = 91724, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 63.2, y = 72.6, n = "Entregar: Suministros de encantamiento robados (Blixie Fitzwink)", q = 91725, a = "T" } } },
      { t = "En el puente, entrega [Informa a Thomas] a Guardia Thomas y acepta [Entrega el informe de Thomas]. En el campamento maderero, entrega [El cumplimiento del plazo] a Supervisor Raelen.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Entregar: Informa a Thomas (Guardia Thomas)", q = 71, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Recoger: Entrega el informe de Thomas (Guardia Thomas)", q = 39, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 81.4, y = 66.1, n = "Entregar: El cumplimiento del plazo (Supervisor Raelen)", q = 5545, a = "T" } } },
      { t = "Al sur del campamento, recoge en el río las herramientas de [Río abajo]. Más al oeste, en el huerto de calabazas, mata a Princesa ([¡Princesa debe morir!]) y a bandidos Defias si te faltan pañuelos. Si ves a Croaky, su cabeza empieza [La cabeza de Croaky]: se entrega en la torre del sureste.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 78.5, y = 79.3, n = "Objetivo: Proteger la frontera", q = 52, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 74.3, y = 76.4, n = "Objetivo: Río abajo", q = 91733, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 69.7, y = 79.2, n = "Objetivo: ¡Princesa debe morir!", q = 88, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 69.3, y = 79.0, n = "Bandidos Defias del huerto", q = 83, a = "C" } } },
      { t = "Entrega [Proteger la frontera] a Guardia Thomas en el puente y, en el campamento, [Río abajo] a Ormin Pelford y [Artículos rojos de lino] a Sara Timberlain.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74.0, y = 72.2, n = "Entregar: Proteger la frontera (Guardia Thomas)", q = 52, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 76.5, y = 71.9, n = "Entregar: Río abajo (Ormin Pelford)", q = 91733, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 79.5, y = 68.8, n = "Entregar: Artículos rojos de lino (Sara Timberlain)", q = 83, a = "T" } } },
      { t = "Vuelve a Villadorada por el camino del sur. En el Lago Cristalino, mata múrlocs para [La recolección de Kelp].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 53.9, y = 66.4, n = "Objetivo: La recolección de Kelp", q = 112, a = "C" } } },
      { t = "En Villadorada entrega [Entrega el informe de Thomas] a Alguacil Dughan y [La Cantera de Jaspe] (acepta [El Cuartel de Arroyoeste necesita ayuda]), y [La recolección de Kelp] a William Mortero: acepta [La fuga].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: Entrega el informe de Thomas (Alguacil Dughan)", q = 39, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: La Cantera de Jaspe (Alguacil Dughan)", q = 76, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Recoger: El Cuartel de Arroyoeste necesita ayuda (Alguacil Dughan)", q = 239, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Entregar: La recolección de Kelp (William Mortero)", q = 112, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Recoger: La fuga (William Mortero)", q = 114, a = "A" } } },
      { t = "Nivel 10: entrena con Zaldimar Wefhellt: Nova de Escarcha (congela a los que tienes cerca: apártate y sigue lanzando), Armadura de Escarcha (rango 2) e Invocar agua (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 43.2, y = 66.2, n = "Zaldimar Wefhellt", npc = 328 } }, comprobar = { hechizos = { 122 } } },
