    entrenar = "En Ventormenta tus instructores de mago están en el Barrio de los Magos: Jennea Cannon y Elsharin; en Forjaz, Nittlebur Chispancio, en el Distrito Místico. Talentos: 10-14 Descarga de Escarcha mejorada.",
    equipo = "Recompensa de [Lago Espejo]: <Bastón Ley> o <Orbe Ley>. Si subes Encantamiento, la <Varita mágica inferior> sirve para rematar y ahorrar maná (en Forever la varita ya no sube con poder con hechizos).",
    profesion = "Sastrería 1-55: <Madeja de paño de lino> y <Cinturón de lino>. Encantamiento 1-20: Motas de magia (Mote of Magic). Primeros auxilios: <Venda de lino>.",
    pasos = {
      { t = "Sigue el camino al norte hasta Ventormenta. En el Distrito de Mercaderes activa el vuelo con Dungar Tragolargo y entrega [Un envío para Ventormenta] a Morgan Mortero.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.2, y = 74.4, n = "Entregar: Un envío para Ventormenta (Morgan Mortero)", q = 61, a = "T" } } },
      { t = "Misión de clase: en el Barrio de los Magos, entrega [Habla con Jennea] a Jennea Cannon y acepta [Lago Espejo]: te da el <Frasco de Jennea> para llenarlo en el Lago Espejo, al sur de la ciudad.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 49.6, y = 85.8, n = "Entregar: Habla con Jennea (Jennea Cannon)", q = 1860, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 49.6, y = 85.8, n = "Recoger: Lago Espejo (Jennea Cannon)", q = 1861, a = "A" } } },
      { t = "Nivel 10: si no entrenaste en Villadorada, hazlo con Jennea Cannon, al lado: Nova de Escarcha, Armadura de Escarcha (rango 2) e Invocar agua (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 49.6, y = 85.8, n = "Jennea Cannon", npc = 5497 } }, comprobar = { hechizos = { 122 } } },
      { t = "Profesiones en el Barrio de los Magos: Encantamiento con Betty Quin, en la tienda de encantamiento, y Sastrería con Lawrence Schneider si no la aprendiste en el campamento maderero. En la Plaza de la Catedral, Shaina Fuller enseña Primeros auxilios.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 73.7, n = "Betty Quin", npc = 11068 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.5, y = 81.5, n = "Lawrence Schneider", npc = 1300 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 44.7, n = "Shaina Fuller", npc = 2327 } }, comprobar = { oficios = { 197, 333, 129 } } },
      { t = "Sal de Ventormenta por el Valle de los Héroes y ve al Lago Espejo, al sur de la ciudad y al oeste del camino de Villadorada: usa el <Frasco de Jennea> en la orilla para coger la <Muestra de agua del Lago Espejo> ([Lago Espejo]).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 28.6, y = 61.4, n = "Objetivo: Lago Espejo", q = 1861, a = "C" } } },
      { t = "Vuelve al Barrio de los Magos y entrega [Lago Espejo] a Jennea Cannon: la guía te marca la mejor recompensa.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 49.6, y = 85.8, n = "Entregar: Lago Espejo (Jennea Cannon)", q = 1861, a = "T" } } },
