  {
    titulo = "Loch Modan", min = 15, max = 18,
    entrenar = "Talentos: 15-17 Mordedura de Escarcha (Frostbite) y 18-19 Fragmentos de hielo. Al 14 aprendes Deflagración Arcana (Arcane Explosion) y al 16 Fogonazo (Flamestrike). Vuela a Forjaz desde Thelsamar para entrenar.",
    equipo = "Busca piezas 'del búho' (Intelecto y Espíritu) en la subasta de Forjaz: a este nivel son baratas. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "El paño de lana cae de troggs y ogros. A sastrería 50 aprende el rango oficial con Jormund Petrocejas y a encantamiento 50 con Gimble Cardopelusa: sin ellos no pasas de 75. Primeros auxilios: <Venda de lino pesado>.",
    pasos = {
      { t = "En el puesto de control del sur acepta [En defensa de las tierras del rey] y [La amenaza trogg]. Mata troggs Rompepiedras al este del puesto.", wp = { { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Recoger: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "A" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Recoger: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.4, y = 75.0, n = "Objetivo: En defensa de las tierras del rey", q = 224, a = "C" }, { m = 1432, z = "Loch Modan", x = 32.3, y = 75.3, n = "Objetivo: La amenaza trogg", q = 267, a = "C" }, { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Entregar: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Entregar: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "T" } } },
      { t = "Thelsamar: piedra de hogar en la posada, activa el vuelo con Thorgrum Borrelson y acepta [Mata ratas], [Morcillas de Thelsamar], [La tarea del montaraz Pico Tormenta] (Montaraz Kadrell) y [La excavación de Vetaferro] (Jern Cornamenta).", wp = { { m = 1432, z = "Loch Modan", x = 35.5, y = 48.4, n = "Tabernero Hogartufa", npc = 6734 }, { m = 1432, z = "Loch Modan", x = 33.9, y = 51.0, n = "Thorgrum Borrelson", npc = 1572 }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Recoger: Mata ratas (Montaraz Kadrell)", q = 416, a = "A" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Recoger: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Recoger: La tarea del montaraz Pico Tormenta (Montaraz Kadrell)", q = 1339, a = "A" }, { m = 1432, z = "Loch Modan", x = 37.2, y = 47.4, n = "Recoger: La excavación de Vetaferro (Jern Cornamenta)", q = 436, a = "A" } } },
      { t = "Haz [Morcillas de Thelsamar] (osos, jabalíes y arañas) y [Mata ratas] (ratas del túnel) al norte de Thelsamar.", wp = { { m = 1432, z = "Loch Modan", x = 34.8, y = 33.9, n = "Objetivo: Morcillas de Thelsamar", q = 418, a = "C" }, { m = 1432, z = "Loch Modan", x = 36.5, y = 22.6, n = "Objetivo: Mata ratas", q = 416, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Entregar: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "T" }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Entregar: Mata ratas (Montaraz Kadrell)", q = 416, a = "T" } } },
      { t = "Al noroeste, junto a la Mina de Arroyoplata, entrega [La tarea del montaraz Pico Tormenta] a Montaraz Pico Tormenta y acepta [Zarpas asquerosas]: recoge dentro de la mina las cuatro cargas de material de minero y entrégasela.", wp = { { m = 1432, z = "Loch Modan", x = 24.8, y = 18.4, n = "Entregar: La tarea del montaraz Pico Tormenta (Montaraz Pico Tormenta)", q = 1339, a = "T" }, { m = 1432, z = "Loch Modan", x = 24.8, y = 18.4, n = "Recoger: Zarpas asquerosas (Montaraz Pico Tormenta)", q = 307, a = "A" }, { m = 1432, z = "Loch Modan", x = 35.5, y = 24.3, n = "Objetivo: Zarpas asquerosas", q = 307, a = "C" }, { m = 1432, z = "Loch Modan", x = 24.8, y = 18.4, n = "Entregar: Zarpas asquerosas (Montaraz Pico Tormenta)", q = 307, a = "T" } } },
      { t = "Nivel 14: vuela de Thelsamar a Forjaz y entrena con Nittlebur Chispancio en el Distrito Místico: Descarga de Escarcha (rango 3), Intelecto Arcano (rango 2) y Explosión de Fuego (rango 2). Vuelve en grifo. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1432, z = "Loch Modan", x = 33.9, y = 51.0, n = "Thorgrum Borrelson", npc = 1572 }, { m = 1455, z = "Forjaz", x = 25.9, y = 6.2, n = "Nittlebur Chispancio", npc = 5146 } }, comprobar = { hechizos = { 837 } } },
      { t = "Cabaña del Errante (este del lago): [La caza de crocoliscos], [La fanfarronada de un cazador] y [Suministros de Bingles] de Bingles Pimpampum. Al lado, Marek Coracero te da [El cuchillo de Marek]: el cocodrilo Daggerfang ronda la orilla del lago, al oeste de la cabaña.", wp = { { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Recoger: La caza de crocoliscos (Marek Coracero)", q = 385, a = "A" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "A" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Recoger: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "A" }, { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Recoger: El cuchillo de Marek (Marek Coracero)", q = 86758, a = "A" } } },
      { t = "Haz [La fanfarronada de un cazador] rápido (15 min) y luego [El reto de un cazador] (12 min). Cocodrilos del lago para [La caza de crocoliscos]; mata también a Daggerfang ([El cuchillo de Marek]) y entrégasela a Marek Coracero.", wp = { { m = 1432, z = "Loch Modan", x = 75.3, y = 73.4, n = "Objetivo: La fanfarronada de un cazador", q = 257, a = "C" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Entregar: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "T" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: El reto de un cazador (Daryl el Jovenzuelo)", q = 258, a = "A" }, { m = 1432, z = "Loch Modan", x = 64.2, y = 39.0, n = "Objetivo: El reto de un cazador", q = 258, a = "C" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Entregar: El reto de un cazador (Daryl el Jovenzuelo)", q = 258, a = "T" }, { m = 1432, z = "Loch Modan", x = 63.2, y = 47.7, n = "Objetivo: La caza de crocoliscos", q = 385, a = "C" }, { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Entregar: La caza de crocoliscos (Marek Coracero)", q = 385, a = "T" }, { m = 1432, z = "Loch Modan", x = 63.3, y = 47.8, n = "Objetivo: El cuchillo de Marek", q = 86758, a = "C" }, { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Entregar: El cuchillo de Marek (Marek Coracero)", q = 86758, a = "T" } } },
      { t = "Recoge las herramientas de Bingles en la orilla norte para [Suministros de Bingles].", wp = { { m = 1432, z = "Loch Modan", x = 51.5, y = 23.7, n = "Objetivo: Suministros de Bingles", q = 2038, a = "C" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Entregar: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "T" } } },
      { t = "Presa del norte: Ingeniero Jefe Hinderweir VII te da [Se aproxima una oscura amenaza]. Busca la pista junto a la rampa este de la presa, vuelve con él y acepta [Se aproxima una oscura amenaza]: se entrega en Los Humedales.", wp = { { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 250, a = "A" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Entregar: Se aproxima una oscura amenaza (Barril sospechoso)", q = 250, a = "T" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Recoger: Se aproxima una oscura amenaza (Barril sospechoso)", q = 199, a = "A" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Entregar: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 199, a = "T" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 161, a = "A" } } },
      { t = "Fortaleza Mo'grosh (nordeste): ogros élite para [Mercenarios] (Magistrado Romonariz, en Thelsamar): misión difícil, recomendable hacerla en grupo.", wp = { { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Recoger: Mercenarios (Magistrado Romonariz)", q = 255, a = "A" }, { m = 1432, z = "Loch Modan", x = 69.9, y = 24.2, n = "Objetivo: Mercenarios", q = 255, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Entregar: Mercenarios (Magistrado Romonariz)", q = 255, a = "T" } } },
      { t = "Excavación de Vetaferro (sureste): entrega [La excavación de Vetaferro] a Magmar Ceñimal y acepta [Recoger ídolos]; Prospector Vetaferro te da [Un informe sobre el avance de la excavación]. Mata troggs en la excavación para los ídolos de [Recoger ídolos] y entrégasela.", wp = { { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Entregar: La excavación de Vetaferro (Magmar Ceñimal)", q = 436, a = "T" }, { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Recoger: Recoger ídolos (Magmar Ceñimal)", q = 297, a = "A" }, { m = 1432, z = "Loch Modan", x = 65.9, y = 65.6, n = "Recoger: Un informe sobre el avance de la excavación (Prospector Vetaferro)", q = 298, a = "A" }, { m = 1432, z = "Loch Modan", x = 70.1, y = 64.2, n = "Objetivo: Recoger ídolos", q = 297, a = "C" }, { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Entregar: Recoger ídolos (Magmar Ceñimal)", q = 297, a = "T" } } },
      { t = "Puesto de control del sur: Montaraz Gravagau te da [En defensa de las tierras del rey], contra los troggs del Valle Rompepiedras, al sureste. Entrégala y acepta [En defensa de las tierras del rey], más al fondo del valle. En el valle, Montaraz Ylva te da [El estandarte de los caídos]: planta el estandarte, mata al trogg que acude y entrégasela a Capitán Rugelfuss en el puesto.", wp = { { m = 1432, z = "Loch Modan", x = 23.5, y = 76.4, n = "Recoger: En defensa de las tierras del rey (Montaraz Gravagau)", q = 237, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.5, y = 85.4, n = "Objetivo: En defensa de las tierras del rey", q = 237, a = "C" }, { m = 1432, z = "Loch Modan", x = 23.5, y = 76.4, n = "Entregar: En defensa de las tierras del rey (Montaraz Gravagau)", q = 237, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.5, y = 74.5, n = "Recoger: En defensa de las tierras del rey (Montaraz Muroplof)", q = 263, a = "A" }, { m = 1432, z = "Loch Modan", x = 31.8, y = 86.3, n = "Recoger: El estandarte de los caídos (Montaraz Ylva)", q = 86585, a = "A" }, { m = 1432, z = "Loch Modan", x = 35.9, y = 91.8, n = "Objetivo: En defensa de las tierras del rey", q = 263, a = "C" }, { m = 1432, z = "Loch Modan", x = 32.3, y = 85.5, n = "Objetivo: El estandarte de los caídos", q = 86585, a = "C" }, { m = 1432, z = "Loch Modan", x = 23.5, y = 74.5, n = "Entregar: En defensa de las tierras del rey (Montaraz Muroplof)", q = 263, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Entregar: El estandarte de los caídos (Capitán Rugelfuss)", q = 86585, a = "T" } } },
      { t = "Vuelve a Thelsamar y entrega [Un informe sobre el avance de la excavación] a Jern Cornamenta.", wp = { { m = 1432, z = "Loch Modan", x = 37.2, y = 47.4, n = "Entregar: Un informe sobre el avance de la excavación (Jern Cornamenta)", q = 298, a = "T" } } },
      { t = "Opcional, al 17-18 y en grupo: en el puesto del sur, la última parte de [En defensa de las tierras del rey], contra el jefe trogg Grawmug y sus guardias.", wp = { { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Capitán Rugelfuss (puesto del sur)", npc = 1092 }, { m = 1432, z = "Loch Modan", x = 34.8, y = 90.5, n = "Gromug, jefe trogg", npc = 1205 } } },
      { t = "Nivel 18: vuela a Forjaz y entrena con Nittlebur Chispancio: Eliminar maldición menor y los rangos nuevos. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 25.9, y = 6.2, n = "Nittlebur Chispancio", npc = 5146 } }, comprobar = { hechizos = { 475 } } },

