      { t = "Punta de Nijel: [Colección de orejas]. Si cogiste [Los negocios de los Reivindicadores en Desolace] en Forjaz (Roetten Rocamartillo), entrégala y haz [Componentes para Reivindicadores y Cía.].", wp = { { m = 1443, z = "Desolace", x = 66.7, y = 10.9, n = "Recoger: Colección de orejas (Cabo Melkins)", q = 1387, a = "A" } } },
