      { t = "Nivel 40: vuela de Costasur a Ventormenta y entrena con Jennea Cannon en el Barrio de los Magos: Nova de Escarcha (rango 3), Armadura de hielo (rango 2), Polimorfia (rango 3) y Descarga de pirofrío. Es caro: guarda también oro para la montura. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 49.6, y = 85.8, n = "Jennea Cannon", npc = 5497 } }, comprobar = { hechizos = { 6131 } } },
